<?php require __DIR__ . "/vendor/autoload.php"; $reader = \PhpOffice\PhpSpreadsheet\IOFactory::createReader("Xlsx"); $spreadsheet = $reader->load("C:/Users/BRYAN/Downloads/Reporte_Reciclaje_02_2026 (1).xlsx"); $sheet = $spreadsheet->getActiveSheet(); echo "Sheets: " . implode(", ", $spreadsheet->getSheetNames()) . PHP_EOL; echo "Rows: " . $sheet->getHighestRow() . PHP_EOL; echo "Cols: " . $sheet->getHighestColumn() . PHP_EOL; for ($row = 1; $row <= min(30, $sheet->getHighestRow()); $row++) { $line = []; for ($col = "A"; $col <= $sheet->getHighestColumn(); $col++) { $val = $sheet->getCell($col . $row)->getValue(); $line[] = $val !== null ? (string)$val : ""; } echo "Row " . str_pad($row, 3) . ": " . implode(" | ", $line) . PHP_EOL; }
